<?php
declare(strict_types=1);
namespace KMM\Core;
/** Fresh-install schema 8. Versioned migrations for existing deployments remain mandatory. */
final class SeedSchema {
    public static function statements():array { return [
        "CREATE TABLE IF NOT EXISTS seed_record_states (seed_key VARCHAR(64) PRIMARY KEY,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,base_json LONGTEXT NOT NULL,seed_version VARCHAR(50) NOT NULL,source_document VARCHAR(2000) NOT NULL,source_checked_on DATE NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_seed_state_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_seed_state_origin FOREIGN KEY(seed_key) REFERENCES project_seed_records(seed_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS seed_user_overlays (seed_key VARCHAR(64) NOT NULL,field_key VARCHAR(64) NOT NULL,value_json LONGTEXT NOT NULL,author_id BIGINT UNSIGNED NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(seed_key,field_key),CONSTRAINT fk_overlay_seed FOREIGN KEY(seed_key) REFERENCES seed_record_states(seed_key),CONSTRAINT fk_overlay_actor FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS seed_update_batches (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,event_key VARCHAR(100) NOT NULL UNIQUE,payload_digest CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,seed_version VARCHAR(50) NOT NULL,source_document VARCHAR(2000) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'processing',changed_count INT UNSIGNED NOT NULL DEFAULT 0,conflict_count INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at DATETIME NULL,INDEX idx_seed_batch_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS seed_merge_conflicts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,seed_key VARCHAR(64) NOT NULL,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,field_key VARCHAR(64) NOT NULL,old_json LONGTEXT NOT NULL,incoming_json LONGTEXT NOT NULL,user_json LONGTEXT NOT NULL,effective_json LONGTEXT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'pending',revision INT UNSIGNED NOT NULL DEFAULT 1,decision VARCHAR(24) NULL,resolver_id BIGINT UNSIGNED NULL,resolved_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_seed_field(batch_id,seed_key,field_key),INDEX idx_conflict_pending(status,id),CONSTRAINT fk_conflict_batch FOREIGN KEY(batch_id) REFERENCES seed_update_batches(id),CONSTRAINT fk_conflict_state FOREIGN KEY(seed_key) REFERENCES seed_record_states(seed_key),CONSTRAINT fk_conflict_company FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS seed_batch_effects (batch_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,PRIMARY KEY(batch_id,company_id),CONSTRAINT fk_seed_effect_batch FOREIGN KEY(batch_id) REFERENCES seed_update_batches(id),CONSTRAINT fk_seed_effect_company FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS seed_admin_notices (admin_id BIGINT UNSIGNED PRIMARY KEY,last_shown_on DATE NOT NULL,last_conflict_id BIGINT UNSIGNED NOT NULL DEFAULT 0,CONSTRAINT fk_seed_notice_user FOREIGN KEY(admin_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS history_import_batches (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,digest CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,format VARCHAR(8) NOT NULL,row_count INT UNSIGNED NOT NULL,operator_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_hist_import_operator FOREIGN KEY(operator_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS history_import_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_event_id VARCHAR(80) NULL,record_type VARCHAR(40) NOT NULL,operation VARCHAR(30) NOT NULL,summary VARCHAR(240) NOT NULL,source_occurred_at VARCHAR(32) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_hist_import_batch(batch_id,id),CONSTRAINT fk_hist_import_batch FOREIGN KEY(batch_id) REFERENCES history_import_batches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
    ]; }
}
